	/// <summary>
    /// Standard Find method for the menu groups.
    /// </summary>
    /// <param name = "_id">Id of the group.</param>
    /// <param name = "_selectForUpdate">Should the record be selected for update?</param>
    /// <returns>A TFMMenuGroups record</returns>
	public static TFMMenuGroups Find (TFMMenuGroupId _id, boolean _selectForUpdate = false)
    {
        TFMMenuGroups menuGroup;

        menuGroup.selectForUpdate(_selectForUpdate);

        select firstonly menuGroup where menuGroup.MenuGroupId == _id;

        return menuGroup;
    }

public static boolean Exist (TFMMenuGroupId _id)
{
    TFMMenuGroups menuGroup;

    select firstonly MenuGroupId from menuGroup where menuGroup.MenuGroupId == _id;

    return menuGroup.MenuGroupId != '';
}

public static boolean addItem(TFMMenuGroupId _menuGroupId, boolean _unattachableInMenus, boolean _showFolder = true)
{
    TFMMenuGroups menuGroup;

    TFMMenuGroups foundGroup = TFMMenuGroups::Find(_menuGroupId);

    if(!foundGroup)
    {
        menuGroup.MenuGroupId = _menuGroupId;
        menuGroup.GroupingTypeIcon = 'Folder';
        menuGroup.Icon =  _menuGroupId;
        menuGroup.Description =  _menuGroupId;
        menuGroup.UnattachableInMenus = _unattachableInMenus;
        menuGroup.insert();

        return true;
    }

    return false;
}

public static void createMenuGroups(TFMPages _pages)
{
    TFMPage             currentTFMPage;
    MapEnumerator       pagesEnum = _pages.getPages().getEnumerator();

    // make sure the main menu has been created.
    TFMMenuGroups::addItem('MainMenu', true, false);

    // create all controls for the pages.
    while (pagesEnum.moveNext())
    {
        currentTFMPage = pagesEnum.currentValue() as TFMPage;

        // Add the Menu Groups that has not been created yet.
        SetEnumerator categoriesEnum = currentTFMPage.getPageBelongsToMenuGroups().getEnumerator();
        while(categoriesEnum.moveNext())
        {
            TFMMenuGroups::addItem(categoriesEnum.current(), TFMMenuGroups::isUnAttachableInMenus(categoriesEnum.current()));
        }
    }
}

public static boolean isUnAttachableInMenus(str _groupName)
{
    return _groupName == TFMConstants::MenuGroupMainMenu() || _groupName == 'ManufacturingExecution';
}

public void delete()
{
    str id = this.MenuGroupId;
    super();
    TFMPagesProvider::getAllPages().removePage(id);
}

/// <summary>
///
/// </summary>
public void insert()
{
    this.MenuGroupId = strKeep(this.MenuGroupId, 'qwertyuioplkjhgfdsazxcvbnm1234567890');
    super();
    //this.updatePageProvider(this);
}

/// <summary>
///
/// </summary>
public void update()
{
    TFMMenuGroupId orgMenuGroupId;		
    this.MenuGroupId = strKeep(this.MenuGroupId, 'qwertyuioplkjhgfdsazxcvbnm1234567890');
    orgMenuGroupId = this.orig().MenuGroupId;
    super();
    if(orgMenuGroupId != this.MenuGroupId)
    {
        TFMPagesProvider::getAllPages().removePage(orgMenuGroupId);
    }
    //this.updatePageProvider(this);
}

public void updatePageProvider()
{
    TFMPageMenuPage page;
    page = TFMPagesProvider::createMenuPage(this);
    TFMPagesProvider::getAllPages().addPage(page);
}
